### Evaluating Arithmetic Expressions

Consider the following attribute grammar for evaluating arithmetic expressions:

    expression(v) → ws term(v) { '+' ws term(w) « v := v + w » }
    term(v) → factor(v) { '*' ws factor(w) « v := v × w » }
    factor(v) → integer(v) | '(' expression(v) ')' ws
    integer(v) → digit(v) { digit(w) « v := 10 × v + w » } ws
    digit(v) → '0' « v := 0 » | … | '9' « v := 9 »
    ws → { ' ' }

The implementation below contains several simplifications:
- the test $sym \in \{'0', '1', … '9'\}$ is implemented by `'0' <= sym <= '9'`,
- if `sym` is a digit, it is converted to an integer by `ord(sym) - ord('0')`.

```python
src: str
pos: int
sym: str

def nxt():
  global pos, sym
  if pos < len(src):
    sym, pos = src[pos], pos + 1
  else:
    sym = chr(0)  # end of input symbol

def expression() -> int:
  # expression(v) → ws term(v) { '+' ws term(w) « v := v + w » }
  ws()
  v = term()
  while sym == '+':
    nxt()
    ws()
    w = term()
    v = v + w
  return v

def term() -> int:
  # term(v) → factor(v) { '*' ws factor(w) « v := v × w » }
  v = factor()
  while sym == '*':
    nxt()
    ws()
    w = factor()
    v = v * w
  return v

def factor() -> int:
  # factor(v) → integer(v) | '(' expression(v) ')' ws
  if '0' <= sym <= '9':
    v = integer()
  elif sym == '(':
    nxt()
    v = expression()
    if sym == ')':
      nxt()
      ws()
    else:
      raise Exception("')' expected at " + str(pos))
  else:
    raise Exception('invalid character at ' + str(pos))
  return v

```python
src: str
pos: int
sym: str

def nxt():
  global pos, sym
  if pos < len(src):
    sym, pos = src[pos], pos + 1
  else:
    sym = chr(0)

def expression() -> int:
  ws()
  v = term()
  while sym in ('+', '-'):
    op = sym
    nxt()
    ws()
    w = term()
    v = v + w if op == '+' else v - w
  return v

def term() -> int:
  v = power()
  while sym in ('*', '/'):
    op = sym
    nxt()
    ws()
    w = power()
    v = v * w if op == '*' else v // w
  return v

def power() -> int:
  v = unary()
  if sym == '^':
    nxt()
    ws()
    w = power()
    v = v**w
  return v

def unary() -> int:
  if sym == '-':
    nxt()
    ws()
    return -unary()
  return factor()

def factor() -> int:
  if '0' <= sym <= '9':
    v = integer()
  elif sym == '(':
    nxt()
    v = expression()
    if sym == ')':
      nxt()
      ws()
    else:
      raise Exception("')' expected at " + str(pos))
  else:
    raise Exception('invalid character at ' + str(pos))
  return v

def integer() -> int:
  v = digit()
  while '0' <= sym <= '9':
    v = 10 * v + digit()
  ws()
  return v

def digit() -> int:
  v = ord(sym) - ord('0')
  nxt()
  return v

def ws():
  while sym == ' ':
    nxt()

def evaluate(s: str) -> int:
  global src, pos
  src, pos = s, 0
  nxt()
  v = expression()
  if sym != chr(0):
    raise Exception('unexpected character at ' + str(pos))
  return v
